// Mock types for testing
typedef unsigned long bitmap_t;

typedef struct {
    size_t ngroups;
    size_t nbits;
} bitmap_info_t;

// Mock BITMAP_GROUP_NBITS
#define LG_SIZEOF_BITMAP 3  // Assume 8-byte unsigned long
#define BITMAP_GROUP_NBITS (1U << (LG_SIZEOF_BITMAP + 3))  // 64
#define BITMAP_GROUP_NBITS_MASK (BITMAP_GROUP_NBITS - 1)

size_t bitmap_ffu(const bitmap_t *bitmap, const bitmap_info_t *binfo, size_t min_bit) {
    if (min_bit >= binfo->nbits) {
        return binfo->nbits;
    }

    size_t group_start = min_bit / BITMAP_GROUP_NBITS;
    size_t bit_offset = min_bit & BITMAP_GROUP_NBITS_MASK;

    for (size_t group = group_start; group < binfo->ngroups; group++) {
        bitmap_t mask = bitmap[group];
        if (mask != ~static_cast<bitmap_t>(0)) {
            // Invert the mask to find the first unset bit
            bitmap_t inverted = ~mask;
            // Find the first set bit in the inverted mask
            bitmap_t masked = inverted >> bit_offset;
            if (masked != 0) {
                return group * BITMAP_GROUP_NBITS + bit_offset + __builtin_ctzl(masked);
            } else {
                // Check the remaining bits in the group
                return group * BITMAP_GROUP_NBITS + __builtin_ctzl(inverted);
            }
        }
        bit_offset = 0;  // Reset for subsequent groups
    }

    return binfo->nbits;
}

